function initSolutionsSwiper(e){if("undefined"==typeof Swiper)return;const n=e.closest(".solutions-section");new Swiper(e,{slidesPerView:"auto",spaceBetween:24,speed:500,grabCursor:!0,keyboard:{enabled:!0},navigation:n?{nextEl:n.querySelector(".solutions-section__nav--next"),prevEl:n.querySelector(".solutions-section__nav--prev")}:void 0})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".solutions-section__swiper").forEach(initSolutionsSwiper)});